record.field:
if record.id:
  con_update = env['x_consignment_header'].search([('id', '=', record.x_studio_consignment_id.id)],limit=1)
  if con_update:
    con_update.write({'x_studio_consolidated': False}) 
    
  last_line = env['x_con_consolidated_lin'].search([('x_studio_consolidated_header_id', '=', record.x_studio_consolidated_header_id.id), ('id', '!=', record.id)],limit=1)
  if not last_line:
    update_con = env['x_con_consolidated_hea'].search([('id', '=', record.x_studio_consolidated_header_id.id)],limit=1)
    if update_con:
        update_con.write({'x_studio_lines_copied': False})

if record.x_studio_invoice_qty:
  
  if record.x_studio_invoice_qty < 0.00:
    raise UserError("Negative Quantities are not Allowed in Item No: " + record.x_studio_description)
  
  purch_line = env['purchase.order.line'].search([('id', '=', record.x_studio_purchase_line_id.id)],limit=1)
  result = 0
  if purch_line:
    con_remainder = 0
    if purch_line.product_qty != purch_line.qty_received:
      con_lines = env['x_consignment_line'].search([('x_studio_purchase_line_id', '=', record.x_studio_purchase_line_id.id), ('id', '!=', record.id)])
      if con_lines:
        for sum_lines in con_lines:
          con_remainder += sum_lines.x_studio_invoice_qty
      
    result = (purch_line.product_qty - con_remainder)
 
  if record.x_studio_invoice_qty > result:
    raise UserError("Quantity to Invoice Should not be exceeding the Consignment Remainder in Item No: " + record.x_studio_description)

cost_allocation = env['x_imports_ledger_setup'].search([('id', '=', 1)], limit=1)
if record.x_studio_supplier_id.id:
  if record.x_studio_supplier_id.property_purchase_currency_id.id:
    record['x_studio_currency_id'] = record.x_studio_supplier_id.property_purchase_currency_id.id

if record.ticket_id:
  company_id = env.context.get('allowed_company_ids', [env.user.company_id.id])[0]
  company = env['res.company'].browse(company_id)
  
  if (record.x_studio_repair_rug == True or record.x_studio_repair_normal_with_serial_no == True):
    if company.id == 1:
      ticket = env['helpdesk.ticket'].search([('id', '=', record.ticket_id.id),('company_id', '=', company.id)],limit=1)
      if ticket:
        if record.location_id.id != record.x_studio_suggested_location_id.id:
          raise UserError("Return Location should be equal to Suggested Return Location.")
    else:
      ticket = env['helpdesk.ticket'].search([('id', '=', record.ticket_id.id),('company_id', '=', company.id)],limit=1)
      if ticket:
        if record.location_id.id != record.x_studio_suggested_location_id_1.id:
          raise UserError('Return Location should be equal to Suggested Return Location.')

if record.state == 'done':
  so = env['sale.order'].search([('id', '=', record.sale_id.id),('state', '=', 'done'),('x_studio_order_payment_method', '=', 'Cash'), ('x_studio_grant_temporary_credit', '=', False)],limit=1)
  if so:
      sum_total = 0
      payment = env['account.payment'].search([('x_studio_sales_order', '=', record.sale_id.id),('state', '=', 'posted')])
      if payment:
        for total in payment:
          sum_total += total.amount
              
      if so.amount_total > sum_total:     
        #raise UserError('The Payment Against the Cash Sales Order must be Registered First.')
        raise UserError('The Payment Against the Cash Sales Order must be Registered First.' + '\n'  + '\n' + 'This sale: ' + str(so.amount_total) + '\n' + 'Total payments: ' + str(sum_total) + '\n' + 'Payment due: ' + str(so.amount_total - sum_total))
